style.css:
@-moz-document domain("deviantart.com") {
/* Background color for the entire page */
    body {
        background-color: #ffcccc !important; /* Light red background */
        color: #ffffff !important; /* White text color */
    }

    /* Adjusting links for better visibility */
    a {
        color: #ffffff !important; /* White links */
    }

    /* Modify header and footer */
    header, footer {
        background-color: #ff9999 !important; /* Slightly darker red */
        color: #ffffff !important;
    }

    /* Customizing buttons */
    button, input[type="button"], input[type="submit"] {
        background-color: #ff6666 !important;
        color: #ffffff !important;
        border: none !important;
    }

    /* Change card or container backgrounds */
    .container, .content, .card {
        background-color: #ffe6e6 !important; /* Lighter red for cards */
        color: #ffffff !important;
    }

    /* Optional: Adjust text fields */
    input, textarea {
        background-color: #ffcccc !important;
        color: #000000 !important; /* Black text for readability */
    }
}
